const IBTN=(v,s,ic,a='')=>BTN({variant:v,size:s,icon:ic,iconOnly:true,aria:ic=='info'?'Details':ic,attrs:a});
const TB=(label,o={})=>`<span class="wtb">${`<small>${esc(label)}</small>`}${o.date?`<b class="dt">${esc(o.date)}</b>`:`<b data-end="${o.end}" data-fmt="dhm">00:00:00</b>`}</span>`;
function CDB(o){const P=parts(o.end-Date.now());const U=[['d','Day'],['h','Hrs'],['m','Min']].concat(o.sec?[['s','Sec']]:[]);return `<div class="wcb ${o.size||'sm'}" data-end="${o.end}"><span class="lb">${esc(o.label||'Ends in')}</span><span class="u">${U.map(([k,u],i)=>`${i?'<i>:</i>':''}<span class="c"><b data-u="${k}">${p2(P[k])}</b><small>${u}</small></span>`).join('')}</span></div>`}
const PB=(v,label,size='sm')=>`<div class="wpb ${size}"><span class="tr"><span class="in" style="width:${v}%"></span></span><span class="lb">${esc(label??v+'%')}</span></div>`;
const STB=(variant,label,icon)=>STATUS({type:'Button',variant,size:'md',indicator:false,icon,label});
const THUMBS=(n=6)=>`<div class="wgm">${range(n).map(()=>'<i class="wph"></i>').join('')}</div>`;
const VDIV='<i class="wvd"></i>';
const SLOT=(l='Layout',st='')=>`<span class="sys-node" style="${st}">${l}</span>`;
const MINDEP='<span class="row xs" style="gap:4px;padding:2px 0">'+'__COINS__'+'Min 30 CAD</span>';
const minDep=()=>MINDEP.replace('__COINS__',I('coins',16));
const NLOCAL=(title,msg,conf,attr)=>`<div class="wnl"><span class="x">${IBTN('Secondary','sm','close','data-lcancel')}</span><div class="hd col" style="gap:4px"><span class="mds">${title}</span><span class="sm c2">${msg}</span></div>${BTN({variant:'Primary',size:'md',label:conf,block:true,attrs:attr})}</div>`;
function cardMount(el,p,set,o={}){$$('[data-cinfo]',el).forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();toast(t('Terms & details'))}));$$('[data-lcancel]',el).forEach(b=>b.addEventListener('click',()=>set({notification:false})));$$('[data-lconf]',el).forEach(b=>b.addEventListener('click',()=>{set({notification:false,...(o.onConfirm||{})});o.msg&&toast(t(o.msg))}));typeof mountInput=='function'&&mountInput(el)}
const CT=(id,name,figma,alias,desc,props,render,extra={})=>reg(Object.assign({id:'card-'+id,name:'Card / '+name,sig:'Card'+name.replace(/[^A-Za-z]/g,''),group:'cards',figma,alias:'card '+alias,desc,props,render,mount:(el,p,set)=>cardMount(el,p,set,extra.cm||{})},extra));
const INFO_BTN=(v,s='sm')=>IBTN(v,s,'info','data-cinfo');

/* 1. Default */
